// Most-specific-first layers, folded with a reducer that keeps the first answer it sees.
export function combine(layers) {
  return layers.reduce((combined, layer) => {
    for (const [key, value] of Object.entries(layer.values ?? {})) {
      if (!Object.hasOwn(combined, key) && value !== undefined) combined[key] = value;
    }
    return combined;
  }, {});
}

export function layerNames(layers) {
  return layers.map((layer) => layer.name);
}
